#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *p = (long long *)malloc((n + 1) * sizeof(long long));
    p[0] = 0;
    for (int i = 0; i < n; i++) {
        long long l;
        scanf("%lld", &l);
        p[i + 1] = p[i] + l;
    }

    long long total = p[n];
    if (total % 2 != 0) {
        printf("N\n");
        free(p);
        return 0;
    }

    long long half = total / 2;
    int diameters = 0;
    int r = 0;

    for (int l = 0; l < n; l++) {
        while (r < n && p[r] - p[l] < half) {
            r++;
        }
        if (r < n && p[r] - p[l] == half) {
            diameters++;
        }
    }

    if (diameters >= 2) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    free(p);
    return 0;
}
